public static class BoundedBatch
{
    public static async Task<int[]> Map(int[] values, int concurrency, Func<int, CancellationToken, ValueTask<int>> work, CancellationToken token)
    {
        if (concurrency < 1)
            throw new ArgumentOutOfRangeException(nameof(concurrency));
        var result = new int[values.Length];
        await Parallel.ForEachAsync(Enumerable.Range(0, values.Length), new ParallelOptions { MaxDegreeOfParallelism = concurrency, CancellationToken = token }, async (index, ct) => result[index] = await work(values[index], ct));
        return result;
    }
}

public static class DeadlineCall
{
    public static async Task<string> Run(Func<CancellationToken, Task<string>> work, TimeSpan timeout, CancellationToken caller)
    {
        if (timeout < TimeSpan.Zero)
            throw new ArgumentOutOfRangeException(nameof(timeout));
        using var deadline = new CancellationTokenSource(timeout);
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(caller, deadline.Token);
        try
        {
            caller.ThrowIfCancellationRequested();
            return await work(linked.Token);
        }
        catch (OperationCanceledException) when (deadline.IsCancellationRequested && !caller.IsCancellationRequested) { throw new TimeoutException("Deadline exceeded"); }
    }
}

public static class FirstResult
{
    public static async Task<int> Run(Func<CancellationToken, Task<int>> left, Func<CancellationToken, Task<int>> right, CancellationToken caller)
    {
        using var stop = CancellationTokenSource.CreateLinkedTokenSource(caller);
        var tasks = new[] { left(stop.Token), right(stop.Token) };
        try
        {
            var first = await Task.WhenAny(tasks);
            return await first;
        }
        finally { stop.Cancel(); try { await Task.WhenAll(tasks); } catch { /* All tasks are observed; the winner's outcome is preserved. */ } }
    }
}

