using System.Threading.Channels;
public static class ChannelRows
{
    public static async Task<int[]> Transfer(int[] values, Func<int, int> transform, CancellationToken token)
    {
        var channel = Channel.CreateBounded<int>(2);
        async Task Produce()
        {
            try
            {
                foreach (var n in values)
                    await channel.Writer.WriteAsync(transform(n), token);
                channel.Writer.TryComplete();
            }
            catch (Exception ex) { channel.Writer.TryComplete(ex); }
        }
        var producer = Produce();
        var rows = new List<int>();
        try
        {
            await foreach (var n in channel.Reader.ReadAllAsync(token))
                rows.Add(n);
        }
        finally { await producer; }
        return rows.ToArray();
    }
}

