public sealed class CatalogDb(DbContextOptions<CatalogDb> options) : DbContext(options)
{
    public DbSet<CatalogCustomer> Customers => Set<CatalogCustomer>(); public DbSet<CatalogItem> Items => Set<CatalogItem>(); protected override void OnModelCreating(ModelBuilder model)
    {
        model.Entity<CatalogItem>().HasIndex(x => x.Name).IsUnique();
        model.Entity<CatalogItem>().HasOne(x => x.Customer).WithMany().HasForeignKey(x => x.CustomerId);
        model.Entity<CatalogItem>().Property(x => x.Version).IsConcurrencyToken();
        model.Entity<CatalogItem>().ToTable("Items", table => table.HasCheckConstraint("positive_quantity", "Quantity > 0"));
    }
}

