public static class ExactlyOne
{
    public static T Pick<T>(IEnumerable<T> values, Func<T, bool> predicate)
    {
        using var rows = values.Where(predicate).GetEnumerator();
        if (!rows.MoveNext())
            throw new KeyNotFoundException();
        T result = rows.Current;
        if (rows.MoveNext())
            throw new InvalidOperationException("Ambiguous selection");
        return result;
    }
}

